'use client';

/**
 * AHOS icon components — one named export per icon, fully tree-shakeable.
 *
 * Generated by ahos_assets/02_icons/tools/src/build.mjs. Do not edit by hand.
 *
 *   import { NavOil, StatusLive, AgentsKian } from './components';
 *   <NavOil variant="gold" size={28} title="نفت" />
 *
 * Every glyph is inline JSX (no loader, no runtime fetch). Gold variants mint a
 * per-instance gradient id via React.useId(), so any number of icons can coexist on
 * one page without id collisions.
 */

import * as React from 'react';
import { useId } from 'react';
import type { SVGProps } from 'react';

export type AhosIconVariant = 'outline' | 'gold' | 'color';

export interface AhosGlyphProps<V extends AhosIconVariant = AhosIconVariant>
  extends Omit<SVGProps<SVGSVGElement>, 'children'> {
  variant?: V;
  size?: number | string;
  className?: string;
  /** Accessible name; without it the glyph is aria-hidden. */
  title?: string;
}

interface IconMeta {
  grid: number;
  variants: AhosIconVariant[];
  title: string;
  titleFa: string;
}

/** Shared root <svg> props: sizing, a11y, and the gold recolour hook. */
export const useIconProps = ({
  title,
  size,
  className,
  variant,
  name,
  grid = 24,
}: {
  title?: string;
  size?: number | string;
  className?: string;
  variant?: AhosIconVariant;
  name?: string;
  grid?: number;
}) => ({
  xmlns: 'http://www.w3.org/2000/svg',
  width: size ?? grid,
  height: size ?? grid,
  viewBox: `0 0 ${grid} ${grid}`,
  className,
  focusable: 'false' as const,
  role: title ? ('img' as const) : undefined,
  'aria-label': title,
  'aria-hidden': title ? undefined : true,
  ...(variant === 'gold' ? { 'data-ahos-gold': '' } : null),
  ...(name ? { 'data-ahos-icon': name } : null),
});

/* ------------------------------------------------------------------ *
 * Nav (28 icons, 24x24 grid)
 * ------------------------------------------------------------------ */

